package io.github.diodeme.ji.provider.http;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** Incremental SSE decoder preserving UTF-8 bytes across arbitrary transport chunks. */
public final class SseDecoder {
    private final ByteArrayOutputStream pending = new ByteArrayOutputStream();
    private String event = "message";
    private final List<String> data = new ArrayList<>();

    public List<Event> feed(ByteBuffer chunk) {
        byte[] bytes = new byte[chunk.remaining()];
        chunk.get(bytes);
        pending.writeBytes(bytes);
        return drain(false);
    }

    public List<Event> finish() {
        return drain(true);
    }

    private List<Event> drain(boolean finish) {
        byte[] bytes = pending.toByteArray();
        int consumed = 0;
        var events = new ArrayList<Event>();
        for (int index = 0; index < bytes.length; index++) {
            if (bytes[index] != '\n') continue;
            processLine(new String(bytes, consumed, index - consumed, StandardCharsets.UTF_8).stripTrailing(), events);
            consumed = index + 1;
        }
        if (finish && consumed < bytes.length) {
            processLine(new String(bytes, consumed, bytes.length - consumed, StandardCharsets.UTF_8).stripTrailing(), events);
            consumed = bytes.length;
        }
        if (finish && (!data.isEmpty() || !event.equals("message"))) emit(events);
        if (consumed > 0) {
            pending.reset();
            pending.write(bytes, consumed, bytes.length - consumed);
        }
        return List.copyOf(events);
    }

    private void processLine(String line, List<Event> events) {
        if (line.isEmpty()) {
            emit(events);
        } else if (line.startsWith("event:")) {
            event = line.substring(6).stripLeading();
        } else if (line.startsWith("data:")) {
            data.add(line.substring(5).stripLeading());
        }
    }

    private void emit(List<Event> events) {
        if (!data.isEmpty()) events.add(new Event(event, String.join("\n", data)));
        event = "message";
        data.clear();
    }

    public record Event(String type, String data) {}
}
